function countPrimesUpTo(limit) {
    const sqrt = Math.floor(Math.sqrt(limit));
    const isPrimeSmall = new Uint8Array(sqrt + 1).fill(1);
    isPrimeSmall[0] = isPrimeSmall[1] = 0;

    for (let i = 2; i * i <= sqrt; i++) {
      if (isPrimeSmall[i]) {
        for (let j = i * i; j <= sqrt; j += i) {
          isPrimeSmall[j] = 0;
        }
      }
    }

    const primes = [];
    for (let i = 2; i <= sqrt; i++) {
      if (isPrimeSmall[i]) primes.push(i);
    }

    const segmentSize = 1_000_000;
    let count = primes.length;

    for (let low = sqrt + 1; low <= limit; low += segmentSize) {
      const high = Math.min(low + segmentSize - 1, limit);
      const isPrime = new Uint8Array(high - low + 1).fill(1);

      for (const p of primes) {
        const start = Math.max(p * p, Math.ceil(low / p) * p);
        for (let j = start; j <= high; j += p) {
          isPrime[j - low] = 0;
        }
      }

      for (let i = 0; i < isPrime.length; i++) {
        if (isPrime[i]) count++;
      }
    }

    return count;
  }
